CREATE TABLE IF NOT EXISTS trade_release(order_id BIGINT PRIMARY KEY, voucher_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS voucher_subscription(voucher_id BIGINT NOT NULL,user_id BIGINT NOT NULL,PRIMARY KEY(voucher_id,user_id));
CREATE TABLE IF NOT EXISTS trade_notice(id BIGINT PRIMARY KEY AUTO_INCREMENT, event_key VARCHAR(128) NOT NULL UNIQUE, user_id BIGINT NOT NULL, content VARCHAR(255) NOT NULL, pushed BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY inbox(user_id,id),KEY dispatch(pushed,id));
